def main():
 acs={r['doi']:r for r in json.loads((L.ROOT/'acs_acquisition.json').read_text())['records']}
 for doi,a in acs.items():
  suffix=doi.split('/')[-1]
  if suffix not in SPECS:continue
  r=next(r for r in L.read('publication_reviews') if r['doi']==doi)
  if r['run_id']!='bootstrap-20261105':continue
  filename,loc,rel,con,note,q=SPECS[suffix];f=next(f for f in a['files'] if f.get('local_file','').endswith(filename));ev=evidence(L.ROOT/'assets'/f['local_file'],f['url'],loc)
  r.update(review_stage='design_sources_reviewed',relevance=rel,catalog_eligibility='unresolved',design_contributions=con,evidence=[ev],rationale=note,unresolved_questions=[q],access='partial',reviewer='Codex inspected source sections; image checks explicitly located',run_id='B0006',date=L.DATE)
  L.upsert('publication_reviews',r,'B0006 source inspection; preserve parent and variant questions')
 # Explicit parent claims; bibliographic identity match is recorded separately from design identity.
 for doi,target,ref in [('10.1021/nl500677j','10.1038/nature04586','SI p.2 design provenance and p.11 reference1: Rothemund Nature2006,440,297–302'),('10.1021/nl5003069','10.1038/nature04586','SI pp.1,3: original tall rectangle, reference1 Rothemund Nature2006,440,297–302'),('10.1021/am501599f','10.1021/nl202066c','SI p.1 template provenance; p.14 reference1 Pilo-Pais et al. Connecting the Nanodots, Nano Lett2011,11,3489–3492')]:
  r=next(r for r in L.read('publication_reviews') if r['doi']==doi);ev=r['evidence'][0]
  L.upsert('discovery_edges',dict(edge_id='design_parent:'+doi+':'+target,source_key=doi,target_key=target,relation='reuses_design_from',evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator=ref,reconciliation_state='bibliographic_parent_matched; exact_design_variant_pending',run_id='B0006',date=L.DATE),'Retain explicit parent attribution without collapsing modified design identity')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0006')
 if b['status']=='completed':print(L.validate());return
 remaining=[k for k in b['input_keys'] if next(r for r in L.read('publication_reviews') if r['registry_key']==k)['review_stage']=='unreviewed']
 b.update(completed_actions=['Inspected fifteen ACS supplement sources; fourteen support design-bearing classifications, one sequence-only case remains uncertain.','Visually inspected tetrahedron-template routing/TEM p4 and SERS variant-list p2.','Recorded three explicit parent-design citation relationships; exact variant mapping remains open.'],after_counts=L.counts(),validation=[L.validate()],unresolved_keys=b['input_keys'],next_queue=remaining)
 L.upsert('batches',b,'Checkpoint fifteen B0006 source reviews;10 balanced inputs remain')
 print(L.validate())
if __name__=='__main__':main()
